fn words(family: u16, sub: u16, fields: &[u32]) -> Vec<u8> {
    let mut bytes = [family.to_le_bytes(), sub.to_le_bytes()].concat();
    for field in fields {
        bytes.extend(field.to_le_bytes());
    }
    bytes
}

