    bytes
}

fn bundle(children: &[Vec<u8>]) -> Vec<u8> {
    let mut bytes = vec![0, 25];
    for child in children {
        assert!((2..255).contains(&child.len()));
        bytes.push(child.len() as u8);
        bytes.extend(child);
    }
    bytes
}

